"""Source-bound construction selection for the six fixed crosswalk cases."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from crosswalk_construction import build_sourced
from crosswalk_measurements import ASSIGNMENT_ID


CASES = {
    "unmarked_wait": ("unmarked", "wait", "permit_pedestrian"),
    "unmarked_pass": ("unmarked", "pass", "permit_pedestrian"),
    "marked_wait": ("marked", "wait", "permit_pedestrian"),
    "marked_pass": ("marked", "pass", "permit_pedestrian"),
    "unmarked_other_stop_wait": ("unmarked", "wait", "other"),
    "unmarked_other_stop_pass": ("unmarked", "pass", "other"),
}


def construct(site_path: str | Path, case_id: str, *, plan_path: str | Path | None = None) -> dict:
    prefix = ASSIGNMENT_ID + "__"
    if not case_id.startswith(prefix) or case_id[len(prefix):] not in CASES:
        raise ValueError("case is not one of the six exact crosswalk constructions")
    if plan_path is None:
        plan_path = Path(__file__).with_name("case-plan.json")
    plan_raw = Path(plan_path).read_bytes()
    plan = json.loads(plan_raw)
    if plan.get("assignment_id") != ASSIGNMENT_ID or case_id not in {c["case_id"] for c in plan.get("cases", [])}:
        raise ValueError("case is absent from the exact case plan")
    crossing, behavior, purpose = CASES[case_id[len(prefix):]]
    site = Path(site_path)
    geometry = build_sourced(site, crosswalk_kind=crossing, ego_behavior=behavior)
    purpose_source = site.parent / geometry["source_inventory"]["stopped_purpose"]["path"]
    observed_purpose = json.loads(purpose_source.read_bytes())
    if observed_purpose.get("source_kind") != "original_observer_statement" or observed_purpose.get("lead_stop_purpose") != purpose:
        raise ValueError("original lead stop purpose differs from exact case")
    geometry.update({"case_id": case_id, "lead_stop_purpose": purpose,
                     "case_plan_sha256": hashlib.sha256(plan_raw).hexdigest(),
                     "capture_plan": {"fps": 20, "frames": 900,
                                      "cameras": ["overview", "approach", "reference_corner", "driver_reference"]},
                     "physical_acceptance_claimed": False, "legal_judgment": "unresolved"})
    return geometry


def compare_constructions(left: dict, right: dict, comparison_id: str,
                          *, plan_path: str | Path | None = None) -> dict:
    """Check declared changes against two source-bound construction proposals."""
    if plan_path is None:
        plan_path = Path(__file__).with_name("case-plan.json")
    plan_raw = Path(plan_path).read_bytes()
    plan = json.loads(plan_raw)
    pairs = {c["comparison_id"]: c["case_ids"] for c in plan.get("comparisons", [])}
    if comparison_id not in pairs or [left.get("case_id"), right.get("case_id")] != pairs[comparison_id]:
        raise ValueError("comparison requires its exact ordered case pair")
    expected_hash = hashlib.sha256(plan_raw).hexdigest()
    for proposal in (left, right):
        if proposal.get("assignment_id") != ASSIGNMENT_ID or proposal.get("case_plan_sha256") != expected_hash:
            raise ValueError("comparison proposal is not bound to the current case plan")
        if proposal.get("physical_acceptance_claimed") is not False or proposal.get("legal_judgment") != "unresolved":
            raise ValueError("comparison proposal asserts a physical or legal conclusion")
    if left.get("map_id") != right.get("map_id") or left.get("capture_plan") != right.get("capture_plan"):
        raise ValueError("comparison changed map or capture conditions")
    for key in ("lead_stop_center", "pedestrian_route"):
        if left.get(key) != right.get(key):
            raise ValueError(f"comparison changed fixed {key}")
    allowed = {"ego_behavior"} if comparison_id != "crosswalk_kind" and comparison_id != "stop_purpose" else ({"crosswalk_kind"} if comparison_id == "crosswalk_kind" else {"lead_stop_purpose"})
    for key in ("crosswalk_kind", "ego_behavior", "lead_stop_purpose"):
        if key in allowed:
            if left.get(key) == right.get(key):
                raise ValueError(f"comparison did not vary {key}")
        elif left.get(key) != right.get(key):
            raise ValueError(f"comparison changed fixed {key}")
    if comparison_id != "crosswalk_kind" and left.get("crosswalk_polygon") != right.get("crosswalk_polygon"):
        raise ValueError("comparison changed fixed crossing geometry")
    if comparison_id == "stop_purpose" and left.get("ego_route") != right.get("ego_route"):
        raise ValueError("comparison changed fixed ego route")
    fixed_sources = {"map", "intersection", "sidewalk", "curb_or_edge", "stopped_purpose"}
    if comparison_id == "stop_purpose":
        fixed_sources.remove("stopped_purpose")
    if left.get("crosswalk_kind") == right.get("crosswalk_kind") == "marked":
        fixed_sources.add("marking")
    for name in fixed_sources:
        if left["source_inventory"].get(name) != right["source_inventory"].get(name):
            raise ValueError(f"comparison changed fixed {name} source")
    return {"comparison_id": comparison_id, "case_ids": pairs[comparison_id],
            "fixed_source_names_checked": sorted(fixed_sources),
            "physical_acceptance_claimed": False, "legal_judgment": "unresolved"}

"""CPU blueprint for a stopped lead and rear-approaching ego at a crosswalk."""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from crosswalk_measurements import ASSIGNMENT_ID


def _point(raw):
    if not isinstance(raw, list) or len(raw) != 2:
        raise ValueError("two-dimensional point required")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) for v in raw):
        raise ValueError("finite point required")
    return [float(raw[0]), float(raw[1])]


def build(site_path: str | Path, *, crosswalk_kind: str, ego_behavior: str) -> dict:
    path = Path(site_path)
    raw = path.read_bytes()
    site = json.loads(raw)
    if site.get("assignment_id") != ASSIGNMENT_ID or not site.get("map_id"):
        raise ValueError("source assignment and map identity required")
    if site.get("junction_kind") != "road_intersection" or site.get("alley_junction") is not False:
        raise ValueError("qualifying road intersection, not alley junction, required")
    if crosswalk_kind not in ("marked", "unmarked") or ego_behavior not in ("wait", "pass"):
        raise ValueError("supported crossing kind and ego behavior required")
    if crosswalk_kind == "unmarked":
        lines = site.get("opposite_sidewalk_lateral_lines")
        if not isinstance(lines, list) or len(lines) != 2 or not site.get("curb_or_traveled_edge_source"):
            raise ValueError("opposite sidewalk lines and curb source required")
        near, far = lines
        if any(not isinstance(line, list) or len(line) != 2 for line in lines):
            raise ValueError("two sidewalk lateral line endpoints required")
        near = [_point(p) for p in near]
        far = [_point(p) for p in far]
        if abs(near[0][0] - far[0][0]) > 0.25 or abs(near[1][0] - far[1][0]) > 0.25:
            raise ValueError("opposite sidewalk lateral lines do not connect")
        polygon = [near[0], near[1], far[1], far[0]]
    else:
        if not site.get("crosswalk_marking_source"):
            raise ValueError("marked crossing source required")
        polygon = [_point(p) for p in site.get("marked_crosswalk_polygon", [])]
        if len(polygon) < 4:
            raise ValueError("marked crossing polygon required")
    lead = _point(site.get("lead_stop_center"))
    ego = _point(site.get("ego_start_center"))
    pedestrian_start = _point(site.get("pedestrian_start"))
    pedestrian_end = _point(site.get("pedestrian_end"))
    road = site.get("road_y_bounds")
    if not isinstance(road, list) or len(road) != 2 or any(not isinstance(x, (int, float)) for x in road) or road[0] >= road[1]:
        raise ValueError("road lateral bounds required")
    if not ego[0] < lead[0] < min(p[0] for p in polygon):
        raise ValueError("ego must start behind stopped lead before crossing")
    if not (road[0] <= lead[1] <= road[1] and road[0] <= ego[1] <= road[1]):
        raise ValueError("vehicle spawn must lie in road bounds")
    if not ((pedestrian_start[1] < road[0] and pedestrian_end[1] > road[1]) or
            (pedestrian_end[1] < road[0] and pedestrian_start[1] > road[1])):
        raise ValueError("pedestrian route must cross the roadway")
    if ego_behavior == "pass":
        pass_y = site.get("pass_lane_y")
        if isinstance(pass_y, bool) or not isinstance(pass_y, (int, float)) or not road[0] <= pass_y <= road[1]:
            raise ValueError("supported road passing lane required")
        ego_half_width = site.get("ego_half_width_m")
        combined_half_width = site.get("combined_vehicle_half_width_m")
        if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or v <= 0
               for v in (ego_half_width, combined_half_width)):
            raise ValueError("positive site vehicle half widths required")
        if not road[0] + ego_half_width <= pass_y <= road[1] - ego_half_width:
            raise ValueError("passing vehicle footprint leaves road bounds")
        if abs(pass_y - lead[1]) < combined_half_width:
            raise ValueError("lateral passing clearance inadequate")
        ego_route = [ego, [lead[0] - 3, float(pass_y)], [max(p[0] for p in polygon) + 3, float(pass_y)]]
    else:
        ego_route = [ego, [lead[0] - 4, ego[1]]]
    return {"assignment_id": ASSIGNMENT_ID, "source": {"path": str(path), "sha256": hashlib.sha256(raw).hexdigest()},
            "map_id": site["map_id"], "crosswalk_kind": crosswalk_kind,
            "crosswalk_polygon": polygon, "lead_stop_center": lead,
            "pedestrian_route": [pedestrian_start, pedestrian_end],
            "ego_route": ego_route, "ego_behavior": ego_behavior,
            "limit": "Geometry and route intent only; original stopped purpose, actor motion and legal crossing status require separate source review."}


def build_sourced(site_path: str | Path, *, crosswalk_kind: str, ego_behavior: str) -> dict:
    """Bind a proposed route to regular source files beside its site packet.

    This checks source custody, not the authority or physical truth of the packet.
    """
    path = Path(site_path)
    site = json.loads(path.read_bytes())
    sources = site.get("sources")
    required = {"map", "intersection", "sidewalk", "curb_or_edge", "stopped_purpose"}
    if crosswalk_kind == "marked":
        required.add("marking")
    if not isinstance(sources, dict) or not required <= sources.keys():
        raise ValueError("complete site source inventory required")
    root = path.parent.resolve()
    inventory = {}
    used = set()
    for name in sorted(required):
        entry = sources[name]
        if not isinstance(entry, dict) or not all(isinstance(entry.get(k), str) and entry[k] for k in ("path", "sha256", "citation")):
            raise ValueError(f"{name} source path, hash and citation required")
        if len(Path(entry["path"]).parts) != 1 or Path(entry["path"]).is_absolute():
            raise ValueError(f"{name} source path must be a portable sibling filename")
        source = path.parent / entry["path"]
        if source.is_symlink() or not source.is_file() or source.resolve().parent != root or source.resolve() == path.resolve():
            raise ValueError(f"{name} must be a distinct regular source beside the site packet")
        if source.resolve() in used:
            raise ValueError("site sources must be distinct files")
        used.add(source.resolve())
        actual = hashlib.sha256(source.read_bytes()).hexdigest()
        if actual != entry["sha256"]:
            raise ValueError(f"{name} source hash mismatch")
        inventory[name] = {"path": entry["path"], "sha256": actual, "citation": entry["citation"]}
    if site.get("map_sha256") != inventory["map"]["sha256"]:
        raise ValueError("site map hash differs from original map source")
    if site.get("curb_or_traveled_edge_source") != sources["curb_or_edge"]["citation"]:
        raise ValueError("curb source citation differs from site geometry")
    if crosswalk_kind == "marked" and site.get("crosswalk_marking_source") != sources["marking"]["citation"]:
        raise ValueError("marking source citation differs from site geometry")
    result = build(path, crosswalk_kind=crosswalk_kind, ego_behavior=ego_behavior)
    result["source_inventory"] = inventory
    result["source_status"] = "bytes_verified_authority_and_physical_truth_unreviewed"
    return result

"""Source-bound physical measurements for LVMC 11.30.030.

The module records position and motion. It never concludes that a driver had a
particular purpose, that an unmarked crossing legally exists, or that a pass
violated the ordinance.
"""

import argparse
import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT_ID = "testing__C229023__LVMC-11-30-030__motor_vehicle_driver"
CASE_SUFFIXES = ("unmarked_wait", "unmarked_pass", "marked_wait", "marked_pass",
                 "unmarked_other_stop_wait", "unmarked_other_stop_pass")
EXPECTED_CONTEXT = {
    "unmarked_wait": ("unmarked", "permit_pedestrian"),
    "unmarked_pass": ("unmarked", "permit_pedestrian"),
    "marked_wait": ("marked", "permit_pedestrian"),
    "marked_pass": ("marked", "permit_pedestrian"),
    "unmarked_other_stop_wait": ("unmarked", "other"),
    "unmarked_other_stop_pass": ("unmarked", "other"),
}


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _point(value):
    if not isinstance(value, list) or len(value) != 2 or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in value):
        raise ValueError("finite two-dimensional point required")
    return value


def _inside(point, polygon):
    x, y = point
    inside = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if (a[1] > y) != (b[1] > y):
            at_x = (b[0] - a[0]) * (y - a[1]) / (b[1] - a[1]) + a[0]
            if x < at_x:
                inside = not inside
    return inside


def _projection(point, origin, axis):
    return (point[0] - origin[0]) * axis[0] + (point[1] - origin[1]) * axis[1]


def _body_extents(vertices, origin, axis):
    if not isinstance(vertices, list) or len(vertices) != 8:
        raise ValueError("eight original world-space body vertices required")
    stations = []
    for vertex in vertices:
        if not isinstance(vertex, list) or len(vertex) != 3 or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in vertex):
            raise ValueError("finite three-dimensional body vertex required")
        stations.append(_projection(vertex[:2], origin, axis))
    if max(stations) - min(stations) <= 0:
        raise ValueError("body has no longitudinal extent")
    return min(stations), max(stations)


def measure(*, case_id, context_path, trace_path, receipt_path, fixture_mode=False):
    """Reopen original bytes and report observed crosswalk approach/pass sequence."""
    if case_id not in {ASSIGNMENT_ID + "__" + suffix for suffix in CASE_SUFFIXES}:
        raise ValueError("unknown exact case ID")
    receipt = json.loads(Path(receipt_path).read_text(encoding="utf-8"))
    if receipt.get("case_id") != case_id or receipt.get("assignment_id") != ASSIGNMENT_ID:
        raise ValueError("source receipt identity mismatch")
    if fixture_mode:
        if receipt.get("diagnostic_fixture") is not True:
            raise ValueError("diagnostic mode requires a marked fixture receipt")
    elif receipt.get("diagnostic_fixture") is not False:
        raise ValueError("diagnostic fixture is not original delivery evidence")
    if _sha(context_path) != receipt.get("context_sha256") or _sha(trace_path) != receipt.get("trace_sha256"):
        raise ValueError("source bytes changed")
    context = json.loads(Path(context_path).read_text(encoding="utf-8"))
    if context.get("case_id") != case_id or not context.get("map_sha256") or len(context["map_sha256"]) != 64:
        raise ValueError("context/map identity missing")
    if context.get("layout") != "intersection" or context.get("junction_kind") != "road_intersection":
        raise ValueError("actual road intersection context required")
    crossing = context.get("crosswalk")
    if not isinstance(crossing, dict) or crossing.get("kind") not in ("marked", "unmarked"):
        raise ValueError("crosswalk kind missing")
    polygon = crossing.get("polygon")
    if not isinstance(polygon, list) or len(polygon) < 4:
        raise ValueError("crosswalk polygon missing")
    polygon = [_point(p) for p in polygon]
    if crossing["kind"] == "unmarked":
        for key in ("opposite_sidewalk_lateral_lines", "curb_or_traveled_edge_sources"):
            if not crossing.get(key):
                raise ValueError("unmarked crosswalk geometry source missing: " + key)
    else:
        if not crossing.get("marking_source"):
            raise ValueError("marked crosswalk source missing")
    purpose = context.get("stopped_vehicle_purpose")
    if not isinstance(purpose, dict) or purpose.get("claim") not in ("permit_pedestrian", "other") or not purpose.get("source_ref"):
        raise ValueError("stopped vehicle purpose needs an independent source")
    expected_crossing, expected_purpose = EXPECTED_CONTEXT[case_id[len(ASSIGNMENT_ID) + 2:]]
    if crossing["kind"] != expected_crossing or purpose["claim"] != expected_purpose:
        raise ValueError("original crossing kind or stopped purpose differs from exact case")
    if not context.get("pedestrian_identity") or not context.get("lead_vehicle_identity") or not context.get("ego_vehicle_identity"):
        raise ValueError("all three actor identities required")
    road = context.get("road_axis")
    if not isinstance(road, dict):
        raise ValueError("road axis missing")
    origin = _point(road.get("origin"))
    axis = _point(road.get("forward"))
    norm = math.hypot(*axis)
    if abs(norm - 1.0) > 0.02:
        raise ValueError("road forward axis must be unit length")
    rows = [json.loads(line) for line in Path(trace_path).read_text(encoding="utf-8").splitlines() if line]
    if len(rows) != receipt.get("frame_count") or len(rows) < 2 or receipt.get("fps") != 20:
        raise ValueError("20 Hz original frame count mismatch")
    observations = []
    prev = None
    for row in rows:
        frame, time_s = row.get("frame"), row.get("time_s")
        if isinstance(frame, bool) or not isinstance(frame, int) or isinstance(time_s, bool) or not isinstance(time_s, (int, float)) or not math.isfinite(time_s):
            raise ValueError("original frame/time missing")
        if prev is not None and (frame != prev[0] + 1 or abs(time_s - prev[1] - .05) > .002):
            raise ValueError("original frame order or cadence mismatch")
        prev = frame, time_s
        ego = _point(row.get("ego_center"))
        lead = _point(row.get("lead_center"))
        pedestrian = _point(row.get("pedestrian_center"))
        ego_rear, ego_front = _body_extents(row.get("ego_vertices"), origin, axis)
        lead_rear, lead_front = _body_extents(row.get("lead_vertices"), origin, axis)
        for key in ("ego_speed_mps", "lead_speed_mps"):
            if isinstance(row.get(key), bool) or not isinstance(row.get(key), (int, float)) or not math.isfinite(row[key]) or row[key] < 0:
                raise ValueError("original speed missing or invalid")
        observations.append({"frame": frame, "time_s": time_s,
                             "ego_station_m": _projection(ego, origin, axis),
                             "lead_station_m": _projection(lead, origin, axis),
                             "ego_rear_station_m": ego_rear, "ego_front_station_m": ego_front,
                             "lead_rear_station_m": lead_rear, "lead_front_station_m": lead_front,
                             "ego_speed_mps": row["ego_speed_mps"],
                             "lead_speed_mps": row["lead_speed_mps"],
                             "pedestrian_in_crosswalk": _inside(pedestrian, polygon)})
    # These are sampled engineering observations, not statutory thresholds.
    rear_approach_frames = [r["frame"] for r in observations if r["ego_front_station_m"] < r["lead_rear_station_m"]]
    stopped_frames = [r["frame"] for r in observations if r["lead_speed_mps"] <= .1]
    pass_frames = [r["frame"] for r in observations if r["ego_rear_station_m"] > r["lead_front_station_m"]]
    crossing_frames = [r["frame"] for r in observations if r["pedestrian_in_crosswalk"]]
    return {"assignment_id": ASSIGNMENT_ID, "case_id": case_id,
            "source_bindings": {"context_sha256": _sha(context_path), "trace_sha256": _sha(trace_path),
                                "receipt_sha256": _sha(receipt_path), "map_sha256": context["map_sha256"]},
            "crosswalk_kind": crossing["kind"], "stopped_vehicle_purpose_claim": purpose["claim"],
            "purpose_source_ref": purpose["source_ref"], "frame_count": len(observations),
            "rear_approach_frames": rear_approach_frames, "lead_stopped_frames": stopped_frames,
            "ego_ahead_frames": pass_frames, "pedestrian_crosswalk_frames": crossing_frames,
            "observations": observations, "legal_judgment": "unresolved",
            "physical_acceptance": "unverified"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--case", required=True)
    parser.add_argument("--context", required=True)
    parser.add_argument("--trace", required=True)
    parser.add_argument("--receipt", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    result = measure(case_id=args.case, context_path=args.context,
                     trace_path=args.trace, receipt_path=args.receipt)
    Path(args.output).write_text(json.dumps(result, sort_keys=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

"""Source-bound Native actors and original per-tick crosswalk observations.

This adapter owns spawned actors. Its route controller is an engineering proposal;
saved measurements, independent audits and physical review decide what occurred.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from crosswalk_measurements import ASSIGNMENT_ID


def _finite(value):
    return type(value) in (int, float) and math.isfinite(value)


def _source_plan(proposal: dict) -> dict:
    case_id = proposal.get("case_id")
    if proposal.get("assignment_id") != ASSIGNMENT_ID or not isinstance(case_id, str) or not case_id.startswith(ASSIGNMENT_ID + "__"):
        raise ValueError("exact source-bound crosswalk proposal required")
    entry = proposal.get("source")
    if not isinstance(entry, dict) or not isinstance(entry.get("path"), str):
        raise ValueError("original site packet source required")
    site_path = Path(entry["path"])
    if site_path.is_symlink() or not site_path.is_file() or hashlib.sha256(site_path.read_bytes()).hexdigest() != entry.get("sha256"):
        raise ValueError("original site packet changed")
    site = json.loads(site_path.read_bytes())
    actor_entry = site.get("sources", {}).get("actor_setup")
    if not isinstance(actor_entry, dict) or any(not isinstance(actor_entry.get(key), str) or not actor_entry[key]
                                                for key in ("path", "sha256", "citation")):
        raise ValueError("reviewed original actor setup source required")
    relative = Path(actor_entry["path"])
    if relative.is_absolute() or len(relative.parts) != 1:
        raise ValueError("actor setup must be a portable sibling source")
    source = site_path.parent / relative
    if source.is_symlink() or not source.is_file() or source.resolve().parent != site_path.parent.resolve():
        raise ValueError("regular original actor setup source required")
    raw = source.read_bytes()
    if hashlib.sha256(raw).hexdigest() != actor_entry["sha256"]:
        raise ValueError("original actor setup source changed")
    plan = json.loads(raw)
    if plan.get("map_id") != proposal.get("map_id") or plan.get("case_id") != proposal.get("case_id"):
        raise ValueError("actor setup map or exact case differs")
    blueprints = plan.get("blueprints")
    heights = plan.get("spawn_z_m")
    if not isinstance(blueprints, dict) or set(blueprints) != {"ego", "lead", "pedestrian"}:
        raise ValueError("three original actor blueprints required")
    if any(not isinstance(value, str) or not value for value in blueprints.values()):
        raise ValueError("nonempty original actor blueprint ID required")
    if not (blueprints["ego"].startswith("vehicle.") and blueprints["lead"].startswith("vehicle.")
            and blueprints["pedestrian"].startswith("walker.pedestrian.")):
        raise ValueError("vehicle and pedestrian Native blueprint kinds required")
    if not isinstance(heights, dict) or set(heights) != set(blueprints) or not all(_finite(value) for value in heights.values()):
        raise ValueError("finite original actor spawn heights required")
    speed = plan.get("ego_target_speed_mps")
    pedestrian_speed = plan.get("pedestrian_speed_mps")
    if not _finite(speed) or not 0 < speed <= 15 or not _finite(pedestrian_speed) or not 0 < pedestrian_speed <= 3:
        raise ValueError("bounded engineering route speeds required")
    return plan


def _xy(location):
    return [float(location.x), float(location.y)]


class NativeCrosswalkActors:
    def __init__(self, *, world, carla, proposal: dict):
        self.world = world
        self.carla = carla
        self.proposal = proposal
        self.plan = _source_plan(proposal)
        cap = proposal.get("engineering_speed_cap_mps")
        if cap is not None:
            if not _finite(cap) or not 0 < cap <= self.plan["ego_target_speed_mps"]:
                raise ValueError("bounded fallback ego speed cap required")
            self.plan = dict(self.plan)
            self.plan["ego_target_speed_mps"] = cap
        self.actors = {}
        self.destroyed = False
        starts = {"ego": proposal["ego_route"][0], "lead": proposal["lead_stop_center"],
                  "pedestrian": proposal["pedestrian_route"][0]}
        destinations = {"ego": proposal["ego_route"][1], "lead": [starts["lead"][0] + 1, starts["lead"][1]],
                        "pedestrian": proposal["pedestrian_route"][1]}
        try:
            library = world.get_blueprint_library()
            for role in ("ego", "lead", "pedestrian"):
                start, destination = starts[role], destinations[role]
                if not (isinstance(start, list) and len(start) == 2 and all(_finite(x) for x in start)
                        and isinstance(destination, list) and len(destination) == 2 and all(_finite(x) for x in destination)):
                    raise ValueError("finite source route coordinates required")
                yaw = math.degrees(math.atan2(destination[1] - start[1], destination[0] - start[0]))
                blueprint = library.find(self.plan["blueprints"][role])
                if blueprint is None:
                    raise ValueError("original actor blueprint missing: " + role)
                transform = carla.Transform(carla.Location(x=start[0], y=start[1], z=self.plan["spawn_z_m"][role]),
                                            carla.Rotation(yaw=yaw))
                actor = world.try_spawn_actor(blueprint, transform)
                if actor is None:
                    raise RuntimeError("Native actor spawn failed: " + role)
                self.actors[role] = actor
            if len({str(actor.id) for actor in self.actors.values()}) != 3:
                raise ValueError("Native actor identities are not distinct")
        except BaseException:
            self.close()
            raise

    @property
    def actor_ids(self):
        return {role: str(actor.id) for role, actor in self.actors.items()}

    def control(self):
        """Apply an explicit route proposal before each synchronous world tick."""
        if self.destroyed:
            raise ValueError("Native actors already destroyed")
        ego = self.actors["ego"]
        position = ego.get_location()
        speed = ego.get_velocity()
        current_speed = math.sqrt(speed.x ** 2 + speed.y ** 2 + speed.z ** 2)
        if not _finite(current_speed):
            raise ValueError("nonfinite original ego speed")
        route = self.proposal["ego_route"]
        target = route[-1]
        if len(route) > 2 and position.x < route[1][0] - 1:
            target = route[1]
        dx, dy = target[0] - position.x, target[1] - position.y
        heading = math.degrees(math.atan2(dy, dx))
        yaw = ego.get_transform().rotation.yaw
        error = (heading - yaw + 180) % 360 - 180
        steer = max(-0.6, min(0.6, error / 45))
        if math.hypot(dx, dy) < 1.5 or self.proposal["ego_behavior"] == "wait" and position.x >= route[-1][0]:
            throttle, brake = 0.0, 1.0
        else:
            throttle = max(0.0, min(0.55, (self.plan["ego_target_speed_mps"] - current_speed) * 0.2))
            brake = 0.0 if current_speed <= self.plan["ego_target_speed_mps"] else 0.25
        ego.apply_control(self.carla.VehicleControl(throttle=throttle, steer=steer, brake=brake))
        self.actors["lead"].apply_control(self.carla.VehicleControl(throttle=0.0, brake=1.0))
        walker = self.actors["pedestrian"]
        walk_start, walk_end = self.proposal["pedestrian_route"]
        walk = walker.get_location()
        wx, wy = walk_end[0] - walk.x, walk_end[1] - walk.y
        distance = math.hypot(wx, wy)
        if distance < 0.3:
            direction, walk_speed = self.carla.Vector3D(x=0, y=0, z=0), 0.0
        else:
            direction = self.carla.Vector3D(x=wx / distance, y=wy / distance, z=0)
            walk_speed = self.plan["pedestrian_speed_mps"]
        walker.apply_control(self.carla.WalkerControl(direction=direction, speed=walk_speed))

    def observe(self, world_frame: int) -> dict:
        if self.destroyed or type(world_frame) is not int or world_frame < 0:
            raise ValueError("live original Native frame required")
        rows = {}
        for role, actor in self.actors.items():
            location = actor.get_location()
            row = {"actor_id": str(actor.id), "center": _xy(location),
                   "source_ref": f"native://world/frame/{world_frame}/actor/{actor.id}"}
            if role != "pedestrian":
                vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
                if len(vertices) != 8:
                    raise ValueError("eight original vehicle body vertices required")
                row["vertices"] = [[float(v.x), float(v.y), float(v.z)] for v in vertices]
                velocity = actor.get_velocity()
                row["speed_mps"] = math.sqrt(velocity.x ** 2 + velocity.y ** 2 + velocity.z ** 2)
            rows[role] = row
        return rows

    def close(self):
        if self.destroyed:
            return
        self.destroyed = True
        for actor in reversed(list(self.actors.values())):
            actor.destroy()

"""Retain original crosswalk actor observations with same-tick camera identities.

The caller owns the CARLA world, actor setup and camera encoding. This adapter
requires a complete 20 Hz capture and writes source files for saved measurement;
it makes no claim about realized crossing geometry, visibility or legality.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from crosswalk_measurements import ASSIGNMENT_ID


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
FRAME_COUNT = 900


def _finite(value):
    return type(value) in (int, float) and math.isfinite(value)


def _center(value):
    if not isinstance(value, list) or len(value) != 2 or not all(_finite(v) for v in value):
        raise ValueError("original two-dimensional center required")
    return value


def _vertices(value):
    if not isinstance(value, list) or len(value) != 8 or any(
        not isinstance(vertex, list) or len(vertex) != 3 or not all(_finite(v) for v in vertex)
        for vertex in value
    ):
        raise ValueError("eight original world-space body vertices required")
    return value


class NativeCrosswalkRecorder:
    def __init__(self, *, case_id: str, context: dict, actor_ids: dict):
        if not isinstance(case_id, str) or not case_id.startswith(ASSIGNMENT_ID + "__"):
            raise ValueError("exact case identity required")
        if not isinstance(context, dict) or context.get("case_id") != case_id:
            raise ValueError("original case context required")
        if not isinstance(actor_ids, dict) or set(actor_ids) != {"ego", "lead", "pedestrian"}:
            raise ValueError("three original actor identities required")
        if any(not isinstance(value, str) or not value.strip() for value in actor_ids.values()):
            raise ValueError("nonempty original actor identities required")
        if len(set(actor_ids.values())) != 3:
            raise ValueError("distinct original actor identities required")
        if any(context.get(key + "_identity") != actor_ids[name] for key, name in
               (("ego_vehicle", "ego"), ("lead_vehicle", "lead"), ("pedestrian", "pedestrian"))):
            raise ValueError("context and original actor identities differ")
        self.case_id = case_id
        self.context = context
        self.actor_ids = dict(actor_ids)
        self.rows = []
        self.frame_map = []

    def append(self, *, world_frame: int, actors: dict, camera_frames: dict) -> dict:
        index = len(self.rows)
        if index >= FRAME_COUNT:
            raise ValueError("capture exceeds planned Native duration")
        if type(world_frame) is not int or world_frame < 0:
            raise ValueError("original integer world frame required")
        if self.rows and world_frame != self.rows[-1]["frame"] + 1:
            raise ValueError("original Native ticks must be consecutive")
        if not isinstance(camera_frames, dict) or set(camera_frames) != set(CAMERAS):
            raise ValueError("four named original camera frames required")
        if any(getattr(camera_frames[name], "frame", None) != world_frame for name in CAMERAS):
            raise ValueError("camera image frame differs from Native world tick")
        if not isinstance(actors, dict) or set(actors) != set(self.actor_ids):
            raise ValueError("all original actors required at every tick")
        for role, observation in actors.items():
            if not isinstance(observation, dict) or observation.get("actor_id") != self.actor_ids[role]:
                raise ValueError("original actor identity differs")
            _center(observation.get("center"))
            if not isinstance(observation.get("source_ref"), str) or str(world_frame) not in observation["source_ref"]:
                raise ValueError("actor source must identify original Native frame")
        for role in ("ego", "lead"):
            _vertices(actors[role].get("vertices"))
            speed = actors[role].get("speed_mps")
            if not _finite(speed) or speed < 0:
                raise ValueError("finite nonnegative original vehicle speed required")
        time_s = index / 20
        row = {"frame": world_frame, "time_s": time_s,
               "ego_center": actors["ego"]["center"], "lead_center": actors["lead"]["center"],
               "pedestrian_center": actors["pedestrian"]["center"],
               "ego_vertices": actors["ego"]["vertices"], "lead_vertices": actors["lead"]["vertices"],
               "ego_speed_mps": actors["ego"]["speed_mps"],
               "lead_speed_mps": actors["lead"]["speed_mps"],
               "actor_sources": {role: actors[role]["source_ref"] for role in self.actor_ids}}
        mapping = {"video_frame": index, "carla_frame": world_frame, "time_s": time_s}
        self.rows.append(row)
        self.frame_map.append(mapping)
        return mapping

    def write(self, directory: str | Path) -> dict:
        if len(self.rows) != FRAME_COUNT:
            raise ValueError("complete 900-frame Native capture required")
        root = Path(directory)
        if not root.is_dir() or any((root / name).exists() for name in
                                    ("context.json", "trace.jsonl", "frame-map.jsonl", "receipt.json")):
            raise ValueError("fresh capture destination required")
        context_raw = (json.dumps(self.context, sort_keys=True, allow_nan=False) + "\n").encode()
        trace_raw = "".join(json.dumps(row, sort_keys=True, allow_nan=False) + "\n" for row in self.rows).encode()
        frame_map_raw = "".join(json.dumps(row, sort_keys=True, allow_nan=False) + "\n" for row in self.frame_map).encode()
        receipt = {"assignment_id": ASSIGNMENT_ID, "case_id": self.case_id,
                   "diagnostic_fixture": False, "fps": 20, "frame_count": FRAME_COUNT,
                   "context_sha256": hashlib.sha256(context_raw).hexdigest(),
                   "trace_sha256": hashlib.sha256(trace_raw).hexdigest(),
                   "frame_map_sha256": hashlib.sha256(frame_map_raw).hexdigest(),
                   "camera_identity_status": "same_tick_only_saved_media_decode_required",
                   "physical_acceptance_claimed": False}
        for name, raw in (("context.json", context_raw), ("trace.jsonl", trace_raw),
                          ("frame-map.jsonl", frame_map_raw),
                          ("receipt.json", (json.dumps(receipt, sort_keys=True) + "\n").encode())):
            (root / name).write_bytes(raw)
        return receipt

"""Four same-tick original CARLA RGB streams for a reviewed crosswalk site.

The site packet supplies each camera's world pose and target. The caller must
bind that packet to its original map and owns the actor/world lifecycle.
"""

from __future__ import annotations

import math
import queue
import subprocess
import time
from pathlib import Path

from native_crosswalk_capture import CAMERAS, FRAME_COUNT
from saved_video_audit import DEFAULT_SIZES


def _xyz(value):
    if not isinstance(value, list) or len(value) != 3 or any(
        type(part) not in (int, float) or not math.isfinite(part) for part in value
    ):
        raise ValueError("finite original three-dimensional camera coordinates required")
    return value


class NativeCrosswalkCameras:
    def __init__(self, *, world, carla, site: dict, output: str | Path,
                 sizes: dict | None = None):
        self.sizes = dict(DEFAULT_SIZES if sizes is None else sizes)
        if set(self.sizes) != set(CAMERAS):
            raise ValueError("four exact camera views required")
        poses = site.get("camera_poses") if isinstance(site, dict) else None
        if not isinstance(poses, dict) or set(poses) != set(CAMERAS):
            raise ValueError("four reviewed original camera poses required")
        self.poses = {}
        for name in CAMERAS:
            row = poses[name]
            if not isinstance(row, dict):
                raise ValueError("original camera pose record required")
            self.poses[name] = (_xyz(row.get("location")), _xyz(row.get("target")))
        self.root = Path(output)
        if not self.root.is_dir() or any((self.root / (name + ".mkv")).exists() for name in CAMERAS):
            raise ValueError("fresh original video destination required")
        self.sensors = []
        self.encoders = {}
        self.queues = {}
        self.errors = []
        self.frames = 0
        self.closed = False
        try:
            library = world.get_blueprint_library()
            for name in CAMERAS:
                width, height = self.sizes[name]
                if type(width) is not int or type(height) is not int or width <= 0 or height <= 0:
                    raise ValueError("positive exact camera dimensions required")
                bp = library.find("sensor.camera.rgb")
                if bp is None:
                    raise ValueError("Native RGB camera blueprint missing")
                for key, value in (("image_size_x", width), ("image_size_y", height), ("fov", 75)):
                    bp.set_attribute(key, str(value))
                location, target = self.poses[name]
                dx, dy, dz = [target[index] - location[index] for index in range(3)]
                if math.hypot(dx, dy) < 0.01:
                    raise ValueError("camera horizontal target direction required")
                yaw = math.degrees(math.atan2(dy, dx))
                pitch = math.degrees(math.atan2(dz, math.hypot(dx, dy)))
                transform = carla.Transform(carla.Location(x=location[0], y=location[1], z=location[2]),
                                            carla.Rotation(pitch=pitch, yaw=yaw))
                sensor = world.spawn_actor(bp, transform)
                if sensor is None:
                    raise RuntimeError("Native camera spawn failed: " + name)
                self.sensors.append(sensor)
                images = queue.Queue(maxsize=8)
                self.queues[name] = images
                def receive(image, *, view=name, target_queue=images):
                    try:
                        target_queue.put_nowait(image)
                    except queue.Full:
                        self.errors.append("camera queue overflow: " + view)
                sensor.listen(receive)
                process = subprocess.Popen([
                    "ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error", "-n",
                    "-f", "rawvideo", "-pixel_format", "bgra", "-video_size", f"{width}x{height}",
                    "-framerate", "20", "-i", "pipe:0", "-an", "-c:v", "ffv1",
                    str(self.root / (name + ".mkv")),
                ], stdin=subprocess.PIPE, stderr=subprocess.DEVNULL)
                self.encoders[name] = process
        except BaseException:
            self.close(require_complete=False)
            raise

    def append(self, world_frame: int):
        if self.closed or type(world_frame) is not int or world_frame < 0:
            raise ValueError("live original Native world frame required")
        if self.frames >= FRAME_COUNT:
            raise ValueError("camera capture exceeds planned duration")
        if self.errors:
            raise RuntimeError("; ".join(self.errors))
        images = {}
        for name in CAMERAS:
            deadline = time.monotonic() + 15
            while True:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise RuntimeError("camera frame timeout: " + name)
                image = self.queues[name].get(timeout=remaining)
                if image.frame < world_frame:
                    continue
                if image.frame != world_frame:
                    raise RuntimeError("camera/world future-frame mismatch: " + name)
                expected = self.sizes[name][0] * self.sizes[name][1] * 4
                if len(image.raw_data) != expected:
                    raise ValueError("original BGRA image size differs: " + name)
                images[name] = image
                break
        if self.errors:
            raise RuntimeError("; ".join(self.errors))
        for name in CAMERAS:
            process = self.encoders[name]
            if process.poll() is not None:
                raise RuntimeError("camera encoder exited early: " + name)
            process.stdin.write(images[name].raw_data)
        self.frames += 1
        return images

    def close(self, *, require_complete: bool = True):
        if self.closed:
            return
        self.closed = True
        errors = []
        for sensor in reversed(self.sensors):
            try:
                sensor.stop()
            except BaseException as exc:
                errors.append(repr(exc))
        for name, process in self.encoders.items():
            try:
                if process.stdin and not process.stdin.closed:
                    process.stdin.close()
                if process.wait(timeout=180) != 0:
                    errors.append("camera encoder failed: " + name)
            except BaseException as exc:
                errors.append(repr(exc))
        for sensor in reversed(self.sensors):
            try:
                sensor.destroy()
            except BaseException as exc:
                errors.append(repr(exc))
        if require_complete and self.frames != FRAME_COUNT:
            errors.append("incomplete 900-frame original camera capture")
        if errors:
            raise RuntimeError("; ".join(errors))

"""Bind a reviewed crosswalk source map to a synchronous Native world session."""

from __future__ import annotations

import copy
import hashlib
from pathlib import Path

from crosswalk_measurements import ASSIGNMENT_ID


def _map_hash(world):
    description = world.get_map().to_opendrive()
    if not isinstance(description, str) or not description:
        raise ValueError("Native world lacks original OpenDRIVE readback")
    return hashlib.sha256(description.encode("utf-8")).hexdigest()


def run_sourced_world(*, world, proposal: dict, capture):
    """Run caller-owned actor/camera capture only on a matching 20 Hz map.

    The callable owns spawning, controller, original pixel encoding and cleanup.
    This wrapper checks site bytes and Native map/settings before any capture.
    """
    if not isinstance(proposal, dict) or proposal.get("assignment_id") != ASSIGNMENT_ID:
        raise ValueError("source-bound exact assignment proposal required")
    source = proposal.get("source")
    inventory = proposal.get("source_inventory")
    if not isinstance(source, dict) or not isinstance(inventory, dict) or "map" not in inventory:
        raise ValueError("site and map source inventory required")
    site_path = Path(source.get("path", ""))
    if site_path.is_symlink() or not site_path.is_file() or hashlib.sha256(site_path.read_bytes()).hexdigest() != source.get("sha256"):
        raise ValueError("original site packet changed")
    entry = inventory["map"]
    if not isinstance(entry, dict) or not isinstance(entry.get("path"), str) or len(Path(entry["path"]).parts) != 1:
        raise ValueError("portable original map source required")
    map_path = site_path.parent / entry["path"]
    if map_path.is_symlink() or not map_path.is_file() or hashlib.sha256(map_path.read_bytes()).hexdigest() != entry.get("sha256"):
        raise ValueError("original map source changed")
    if _map_hash(world) != entry["sha256"]:
        raise ValueError("loaded Native map differs from reviewed source map")
    if world.get_map().name != proposal.get("map_id"):
        raise ValueError("loaded Native map identity differs")
    if not callable(capture):
        raise ValueError("Native capture callable required")
    original = world.get_settings()
    desired = copy.copy(original)
    desired.synchronous_mode = True
    desired.fixed_delta_seconds = .05
    try:
        world.apply_settings(desired)
        active = world.get_settings()
        if active.synchronous_mode is not True or active.fixed_delta_seconds != .05:
            raise ValueError("Native world did not read back synchronous 20 Hz settings")
        result = capture(world)
        if _map_hash(world) != entry["sha256"]:
            raise ValueError("Native map changed during crosswalk capture")
        return {"case_id": proposal["case_id"], "map_sha256": entry["sha256"],
                "capture_result": result, "physical_acceptance_claimed": False}
    finally:
        world.apply_settings(original)

"""Independently reopen the original Native clock and actor source packet."""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from crosswalk_measurements import ASSIGNMENT_ID
from native_crosswalk_capture import FRAME_COUNT


def _rows(path):
    return [json.loads(line) for line in Path(path).read_text(encoding="utf-8").splitlines() if line]


def audit(*, directory: str | Path, case_id: str, fixture_mode: bool = False) -> dict:
    root = Path(directory)
    receipt = json.loads((root / "receipt.json").read_text(encoding="utf-8"))
    if receipt.get("assignment_id") != ASSIGNMENT_ID or receipt.get("case_id") != case_id or receipt.get("diagnostic_fixture") is not fixture_mode:
        raise ValueError("original exact-case receipt required")
    if receipt.get("fps") != 20 or receipt.get("frame_count") != FRAME_COUNT:
        raise ValueError("complete original capture profile required")
    for name, field in (("context.json", "context_sha256"), ("trace.jsonl", "trace_sha256"),
                        ("frame-map.jsonl", "frame_map_sha256")):
        if hashlib.sha256((root / name).read_bytes()).hexdigest() != receipt.get(field):
            raise ValueError(f"changed original {name} bytes")
    context = json.loads((root / "context.json").read_text(encoding="utf-8"))
    if context.get("case_id") != case_id:
        raise ValueError("original context case differs")
    trace, mapping = _rows(root / "trace.jsonl"), _rows(root / "frame-map.jsonl")
    if len(trace) != FRAME_COUNT or len(mapping) != FRAME_COUNT:
        raise ValueError("incomplete original Native tick and camera map")
    ids = {"ego": context.get("ego_vehicle_identity"), "lead": context.get("lead_vehicle_identity"),
           "pedestrian": context.get("pedestrian_identity")}
    if any(not isinstance(v, str) or not v for v in ids.values()) or len(set(ids.values())) != 3:
        raise ValueError("three distinct original actor identities required")
    first = trace[0].get("frame")
    if type(first) is not int or first < 0:
        raise ValueError("original Native starting frame required")
    for index, (row, frame_map) in enumerate(zip(trace, mapping)):
        frame = first + index
        if (type(row.get("frame")) is not int or type(frame_map.get("carla_frame")) is not int
                or type(frame_map.get("video_frame")) is not int
                or row["frame"] != frame or frame_map["carla_frame"] != frame
                or frame_map["video_frame"] != index):
            raise ValueError("actor and camera frame join differs")
        time_s = index / 20
        if any(type(value) not in (int, float) or not math.isfinite(value) or abs(value - time_s) > 1e-6
               for value in (row.get("time_s"), frame_map.get("time_s"))):
            raise ValueError("actor and camera 20 Hz clock differs")
        sources = row.get("actor_sources")
        if not isinstance(sources, dict) or set(sources) != set(ids) or any(
            not isinstance(sources[role], str) or str(frame) not in sources[role] for role in ids
        ):
            raise ValueError("original actor source join missing")
    return {"assignment_id": ASSIGNMENT_ID, "case_id": case_id, "frame_count": FRAME_COUNT,
            "first_native_frame": first, "last_native_frame": first + FRAME_COUNT - 1,
            "trace_sha256": receipt["trace_sha256"],
            "frame_map_sha256": receipt["frame_map_sha256"],
            "camera_status": "same_tick_identity_only_saved_media_decode_required",
            "physical_acceptance": "unverified", "legal_judgment": "unresolved"}

"""Independent saved-source comparison for the five exact crosswalk pairs."""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from crosswalk_measurements import ASSIGNMENT_ID, measure
from saved_video_audit import audit as audit_video


def _rows(path: Path) -> list[dict]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line]


def _close_xy(left, right, tolerance_m: float = 0.25) -> bool:
    if not all(isinstance(value, list) and len(value) == 2 and all(
        type(part) in (int, float) and math.isfinite(part) for part in value
    ) for value in (left, right)):
        raise ValueError("finite original comparison centers required")
    return math.dist(left, right) <= tolerance_m


def _recompute(root: Path, case_id: str) -> tuple[dict, dict, dict, list[dict]]:
    measured = measure(case_id=case_id, context_path=root / "context.json",
                       trace_path=root / "trace.jsonl", receipt_path=root / "receipt.json")
    media = audit_video(directory=root, case_id=case_id)
    context = json.loads((root / "context.json").read_text(encoding="utf-8"))
    trace = _rows(root / "trace.jsonl")
    return measured, media, context, trace


def audit(*, left_dir: str | Path, right_dir: str | Path,
          comparison_id: str, plan_path: str | Path | None = None) -> dict:
    if plan_path is None:
        plan_path = Path(__file__).with_name("case-plan.json")
    plan_raw = Path(plan_path).read_bytes()
    plan = json.loads(plan_raw)
    if plan.get("assignment_id") != ASSIGNMENT_ID:
        raise ValueError("exact assignment comparison plan required")
    pairs = {row["comparison_id"]: row["case_ids"] for row in plan.get("comparisons", [])}
    if comparison_id not in pairs:
        raise ValueError("unknown exact crosswalk comparison")
    roots = [Path(left_dir), Path(right_dir)]
    reports = []
    recomputed = []
    for root, case_id in zip(roots, pairs[comparison_id]):
        path = root / "crosswalk-measurement.json"
        if path.is_symlink() or not path.is_file():
            raise ValueError("saved original measurement missing")
        report = json.loads(path.read_text(encoding="utf-8"))
        if report.get("assignment_id") != ASSIGNMENT_ID or report.get("case_id") != case_id:
            raise ValueError("saved report exact case differs")
        if report.get("physical_acceptance") != "unverified" or report.get("legal_verdict_claimed") is not False:
            raise ValueError("saved report asserts unsupported physical or legal acceptance")
        measured, media, context, trace = _recompute(root, case_id)
        if report.get("measured_values") != measured or report.get("media") != media:
            raise ValueError("saved report differs from original source recomputation")
        expected_observed = {
            "rear_approach_sampled": bool(measured["rear_approach_frames"]),
            "lead_stop_sampled": bool(measured["lead_stopped_frames"]),
            "pedestrian_in_polygon_sampled": bool(measured["pedestrian_crosswalk_frames"]),
            "ego_full_pass_sampled": bool(measured["ego_ahead_frames"]),
        }
        if report.get("observed") != expected_observed:
            raise ValueError("saved observed flags differ from original source recomputation")
        current_hashes = {name: hashlib.sha256((root / name).read_bytes()).hexdigest()
                          for name in ("context.json", "trace.jsonl", "frame-map.jsonl", "receipt.json")}
        if report.get("source_sha256") != current_hashes:
            raise ValueError("saved report original source hash differs")
        reports.append((path, report))
        recomputed.append((measured, media, context, trace))
    left, right = recomputed
    left_measure, left_media, left_context, left_trace = left
    right_measure, right_media, right_context, right_trace = right
    for key in ("map_sha256", "junction_kind", "layout", "road_axis"):
        if left_context.get(key) != right_context.get(key):
            raise ValueError("comparison changed fixed original " + key)
    if left_measure["frame_count"] != 900 or right_measure["frame_count"] != 900:
        raise ValueError("comparison lacks complete original 45-second captures")
    if len(left_trace) != len(right_trace) or any(
        not _close_xy(a.get("lead_center"), b.get("lead_center")) or
        not _close_xy(a.get("pedestrian_center"), b.get("pedestrian_center"))
        for a, b in zip(left_trace, right_trace)
    ):
        raise ValueError("comparison changed fixed lead or pedestrian trajectory")
    for name in left_media["videos"]:
        if left_media["videos"][name]["frames"] != right_media["videos"][name]["frames"]:
            raise ValueError("comparison changed camera duration")
    changed = {"crosswalk_kind": left_measure["crosswalk_kind"] != right_measure["crosswalk_kind"],
               "lead_stop_purpose": left_measure["stopped_vehicle_purpose_claim"] != right_measure["stopped_vehicle_purpose_claim"],
               "ego_full_pass": bool(left_measure["ego_ahead_frames"]) != bool(right_measure["ego_ahead_frames"])}
    requested = "crosswalk_kind" if comparison_id == "crosswalk_kind" else (
        "lead_stop_purpose" if comparison_id == "stop_purpose" else "ego_full_pass"
    )
    if not changed[requested] or any(value for key, value in changed.items() if key != requested):
        raise ValueError("comparison observed difference differs from declared variable")
    if comparison_id != "crosswalk_kind" and left_context["crosswalk"] != right_context["crosswalk"]:
        raise ValueError("comparison changed fixed crosswalk geometry")
    if comparison_id != "stop_purpose" and left_context["stopped_vehicle_purpose"] != right_context["stopped_vehicle_purpose"]:
        raise ValueError("comparison changed fixed lead stop purpose source")
    return {"comparison_id": comparison_id, "case_ids": pairs[comparison_id],
            "plan_sha256": hashlib.sha256(plan_raw).hexdigest(),
            "saved_report_sha256": [hashlib.sha256(path.read_bytes()).hexdigest() for path, _ in reports],
            "declared_difference": requested, "measured_difference": changed,
            "fixed_source_conditions_checked": ["map_sha256", "junction_kind", "layout",
                                                "road_axis", "lead_trajectory", "pedestrian_trajectory",
                                                "camera_duration"],
            "physical_acceptance": "unverified", "legal_judgment": "unresolved"}

"""Decode all four saved Native videos and join them to original world ticks.

This is a source and media integrity check. It does not certify that the
pedestrian, lead vehicle, crosswalk or passing maneuver is physically visible.
"""

from __future__ import annotations

import hashlib
import json
import subprocess
from pathlib import Path

from native_crosswalk_capture import CAMERAS, FRAME_COUNT
from saved_capture_audit import audit as audit_capture


DEFAULT_SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
                 "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


def _file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _probe(path: Path) -> dict:
    run = subprocess.run(["ffprobe", "-v", "error", "-select_streams", "v:0",
                          "-show_entries", "stream=codec_name,width,height,avg_frame_rate",
                          "-of", "json", str(path)], capture_output=True, text=True, check=True)
    streams = json.loads(run.stdout).get("streams", [])
    if len(streams) != 1:
        raise ValueError("one original video stream required: " + path.name)
    return streams[0]


def _decode(path: Path, width: int, height: int, expected_frames: int) -> dict:
    frame_bytes = width * height * 3
    process = subprocess.Popen(["ffmpeg", "-nostdin", "-v", "error", "-i", str(path),
                                "-map", "0:v:0", "-an", "-f", "rawvideo", "-pix_fmt", "rgb24",
                                "pipe:1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    digest = hashlib.sha256()
    first_digest = None
    distinct = False
    frames = 0
    try:
        while True:
            block = process.stdout.read(frame_bytes)
            if not block:
                break
            if len(block) != frame_bytes:
                raise ValueError("truncated decoded camera frame: " + path.name)
            frames += 1
            if frames > expected_frames:
                raise ValueError("extra decoded camera frame: " + path.name)
            frame_digest = hashlib.sha256(block).digest()
            if first_digest is None:
                first_digest = frame_digest
            elif frame_digest != first_digest:
                distinct = True
            digest.update(block)
        error = process.stderr.read().decode("utf-8", "replace")
        if process.wait() != 0:
            raise ValueError("camera decoder failed: " + path.name + ": " + error[-400:])
    finally:
        if process.poll() is None:
            process.kill()
            process.wait()
        process.stdout.close()
        process.stderr.close()
    if frames != expected_frames:
        raise ValueError("incomplete decoded camera: " + path.name)
    return {"frames": frames, "rgb_sha256": digest.hexdigest(),
            "varied_frames": distinct}


def audit(*, directory: str | Path, case_id: str,
          sizes: dict[str, tuple[int, int]] | None = None,
          expected_frames: int = FRAME_COUNT, fixture_mode: bool = False) -> dict:
    root = Path(directory)
    if sizes is None:
        sizes = DEFAULT_SIZES
    if set(sizes) != set(CAMERAS) or expected_frames < 2:
        raise ValueError("four exact camera views and at least two frames required")
    capture = audit_capture(directory=root, case_id=case_id, fixture_mode=fixture_mode)
    if capture["frame_count"] != expected_frames:
        raise ValueError("saved video and original frame map counts differ")
    videos = {}
    for name in CAMERAS:
        path = root / (name + ".mkv")
        if path.is_symlink() or not path.is_file():
            raise ValueError("original camera video missing: " + name)
        width, height = sizes[name]
        if type(width) is not int or type(height) is not int or width <= 0 or height <= 0:
            raise ValueError("positive exact camera dimensions required")
        stream = _probe(path)
        if (stream.get("codec_name") != "ffv1" or stream.get("width") != width
                or stream.get("height") != height or stream.get("avg_frame_rate") != "20/1"):
            raise ValueError("original camera encoding/profile differs: " + name)
        decoded = _decode(path, width, height, expected_frames)
        videos[name] = {"video_sha256": _file_sha256(path), **decoded}
    return {"case_id": case_id, "frame_map_sha256": capture["frame_map_sha256"],
            "first_native_frame": capture["first_native_frame"],
            "last_native_frame": capture["last_native_frame"], "videos": videos,
            "physical_acceptance": "unverified", "legal_judgment": "unresolved"}
